#[derive(Debug, Clone, Copy)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct SHA512 {
    pub state: [u64; 8],
    pub buffer: [u8; 128],
    pub count: u64,
}

pub fn big_sigma0(x: u64) -> u64 {
    return ((rotr(x, 28) ^ rotr(x, 34)) ^ rotr(x, 39));
}

pub fn big_sigma1(x: u64) -> u64 {
    return ((rotr(x, 14) ^ rotr(x, 18)) ^ rotr(x, 41));
}

pub fn ch(x: u64, y: u64, z: u64) -> u64 {
    return ((x & y) ^ ((x ^ ALL) & z));
}

pub fn compress(sha: &mut SHA512) -> () {
    let mut w: [u64; 80] = [0; 80];
    let mut t: usize = 0;
    while (t < 16) {
        let mut word: u64 = 0;
        let mut b: usize = 0;
        while (b < 8) {
            word = ((word << 8) | (sha.buffer[(((t * 8) + b)) as usize] as u64));
            b = (b + 1);
        }
        w[(t) as usize] = word;
        t = (t + 1);
    }
    while (t < 80) {
        w[(t) as usize] = (((small_sigma1(w[((t - 2)) as usize])).wrapping_add(w[((t - 7)) as usize])).wrapping_add(small_sigma0(w[((t - 15)) as usize]))).wrapping_add(w[((t - 16)) as usize]);
        t = (t + 1);
    }
    let mut v: [u64; 8] = [0; 8];
    let mut k: usize = 0;
    while (k < 8) {
        v[(k) as usize] = sha.state[(k) as usize];
        k = (k + 1);
    }
    t = 0;
    while (t < 80) {
        let t1 = ((((v[7]).wrapping_add(big_sigma1(v[4]))).wrapping_add(ch(v[4], v[5], v[6]))).wrapping_add(K[(t) as usize])).wrapping_add(w[(t) as usize]);
        let t2 = (big_sigma0(v[0])).wrapping_add(maj(v[0], v[1], v[2]));
        v[7] = v[6];
        v[6] = v[5];
        v[5] = v[4];
        v[4] = (v[3]).wrapping_add(t1);
        v[3] = v[2];
        v[2] = v[1];
        v[1] = v[0];
        v[0] = (t1).wrapping_add(t2);
        t = (t + 1);
    }
    k = 0;
    while (k < 8) {
        sha.state[(k) as usize] = (sha.state[(k) as usize]).wrapping_add(v[(k) as usize]);
        k = (k + 1);
    }
}

pub fn finish(sha: &mut SHA512) -> [u8; 64] {
    let len_hi = (sha.count >> 61);
    let len_lo = (sha.count).wrapping_mul(8);
    let used = ((sha.count % 128) as usize);
    let mut zeros: usize = (239 - used);
    if (used < 112) {
        zeros = (111 - used);
    }
    let mut pad: [u8; 144] = [0; 144];
    pad[0] = 128;
    let mut k: usize = 0;
    while (k < 8) {
        pad[(((1 + zeros) + k)) as usize] = (((len_hi >> (56 - (8 * (k as u64)))) & 255) as u8);
        pad[(((9 + zeros) + k)) as usize] = (((len_lo >> (56 - (8 * (k as u64)))) & 255) as u8);
        k = (k + 1);
    }
    update(sha, &pad[(0) as usize..((zeros + 17)) as usize]);
    let mut out: [u8; 64] = [0; 64];
    let mut i: usize = 0;
    while (i < 64) {
        out[(i) as usize] = (((sha.state[((i / 8)) as usize] >> (56 - (8 * ((i % 8) as u64)))) & 255) as u8);
        i = (i + 1);
    }
    return out;
}

pub fn hash(data: &[u8]) -> [u8; 64] {
    let mut sha = init();
    update(&mut (sha), data);
    return finish(&mut (sha));
}

pub fn init() -> SHA512 {
    return SHA512 { state: H0, buffer: [0; 128], count: 0 };
}

pub fn maj(x: u64, y: u64, z: u64) -> u64 {
    return (((x & y) ^ (x & z)) ^ (y & z));
}

pub fn rotr(x: u64, n: u64) -> u64 {
    return ((x >> n) | (x << (64 - n)));
}

pub fn small_sigma0(x: u64) -> u64 {
    return ((rotr(x, 1) ^ rotr(x, 8)) ^ (x >> 7));
}

pub fn small_sigma1(x: u64) -> u64 {
    return ((rotr(x, 19) ^ rotr(x, 61)) ^ (x >> 6));
}

pub fn update(sha: &mut SHA512, data: &[u8]) -> () {
    let mut i: usize = 0;
    while (i < data.len()) {
        sha.buffer[(((sha.count % 128) as usize)) as usize] = data[(i) as usize];
        sha.count = (sha.count + 1);
        if ((sha.count % 128) == 0) {
            compress(sha);
        }
        i = (i + 1);
    }
}

